/* ------ Program Assumption ------*/

wire program_0 = \gold.memi_instance.array_mem [0] == \gate.memi_instance.array_mem [0];
wire program_1 = \gold.memi_instance.array_mem [1] == \gate.memi_instance.array_mem [1];
