wire program_equiv = program_0 && program_1 && program_2 && program_3 && program_4 && program_5 && program_6 && program_7;
assume (program_equiv);

reg gate_stall_signal;
reg gold_stall_signal;

always @(posedge in_clk) begin
    if (in_rst) begin
     gate_stall_signal = 0 ; 
     gold_stall_signal = 0 ; 

    end else begin

     gate_stall_signal = \gate.rob_instance.C_valid && ! \gold.rob_instance.C_valid ; 
     gold_stall_signal = \gold.rob_instance.C_valid && ! \gate.rob_instance.C_valid ; 
    end
end

    wire C_mem_addr_observation = \gold.C_mem_valid == \gate.C_mem_valid  && \gold.C_mem_rdwt == \gate.C_mem_rdwt  && ( !(\gold.C_mem_valid == 1 && \gold.C_mem_rdwt == 1) || \gold.C_mem_addr == \gate.C_mem_addr );
    wire C_taken_observation = \gold.C_is_br == \gate.C_is_br  && ( !(\gold.C_is_br == 1) || \gold.C_taken == \gate.C_taken );
    wire contract_leakage = !( \gold.rob_instance.C_valid && \gate.rob_instance.C_valid ) || (C_mem_addr_observation && C_taken_observation ); 
    assume (contract_leakage ); 

wire commit_deviation = ( \gold.rob_instance.C_valid == \gate.rob_instance.C_valid );
// wire addr_deviation = ( \gold.rob_instance.ld_addr == \gate.rob_instance.ld_addr );

    wire trg_equiv = commit_deviation ; // && addr_deviation;

    reg [6: 0]  bound = 35;

    always @ (posedge in_clk) begin
        if (bound > 0 && !state_trg_equiv) begin
            bound <= bound - 1;
        end
    end

    // update the states for verification
    reg state_trg_equiv = 1;
    always @ (posedge in_clk) begin
            state_trg_equiv <= state_trg_equiv && trg_equiv;
    end

    wire fin_state_trg_equiv = ( bound > 0 || gate_stall_signal || gold_stall_signal) ||  state_trg_equiv ;

    assert  (fin_state_trg_equiv);

